import assert from 'node:assert/strict';
import {readFile} from 'node:fs/promises';
import {createHash} from 'node:crypto';
import {mountInterface,mountInterfacePreview,plain} from './interface-dom.js';
import {waitFor} from './app-dom.js';
import {addDays} from '../src/date-utils.js';
import {searchFeed} from '../src/app-utils.js';
import {paceWeights,paceGoals} from './nutrition-fixtures.js';
const date='2026-10-18', prior='2026-10-17';
const seed={goals:{sex:'hombre',autoMacros:false},weights:[{id:'w',date,kg:70},{id:'old',date:prior,kg:69}],wellness:[{id:'s',date,steps:8000,sleep:7}],measurements:[{id:'m',date,cintura:80}],nutrition:[{id:'n',date,name:'Avena',kcal:200,protein:8,carbs:30,fat:4}],workouts:[{id:'t',date,exercises:[{id:'e',name:'Remo',primary:'Espalda',sets:[{id:'set',reps:8,kg:20,rpe:8}]}]}]};
const h1=a=>a.w.document.querySelector('h1')?.textContent;
const findButton=(a,text)=>[...a.w.document.querySelectorAll('button')].find(b=>b.textContent.trim()===text);
const done=async(a,fn)=>{try{await fn(a);}finally{await a.close();}};
const heading=async(a,text)=>waitFor(()=>h1(a)===text,'cabecera '+text);
export const cases={
 async navigation(options={}) {await done(await mountInterface(seed,{mode:'app'},options),async a=>{
  await a.ready();assert.deepEqual([...a.w.document.querySelectorAll('.ft-nav button[title]')].map(b=>b.title),['Registrar','Diario','Plan','Métricas','Biblioteca']);
  assert.deepEqual([...a.w.document.querySelectorAll('.ft-tabbar button')].map(b=>b.textContent),['Diario','Métricas','Añadir','Plan','Biblioteca']);
  for(const [title,tab]of [['Plan','plan'],['Métricas','dashboard'],['Biblioteca','biblioteca'],['Diario','diario']]){await a.click(`.ft-nav button[title="${title}"]`);assert.equal(a.app.tab,tab);assert.equal(a.w.document.querySelector('.ft-nav .active').title,title);}
  await a.click('.ft-side-logo');assert(a.w.document.querySelector('.ft-side.open'));await a.act(()=>a.w.document.querySelector('.ft-side').dispatchEvent(new a.w.MouseEvent('mouseout',{bubbles:true,relatedTarget:a.w.document.body})));assert.equal(a.app.menuOpen,false);
  await a.click('.ft-user');assert.equal(a.app.tab,'cuenta');await waitFor(()=>findButton(a,'PERFIL'),'cuenta montada');assert(a.w.document.querySelector('.ft-user.active'));
 });},
 async registration() {for(const sex of ['hombre','mujer'])await done(await mountInterface({...seed,goals:{...seed.goals,sex}},{mode:'app'}),async a=>{
  await a.ready();await a.click('.ft-nav-add');const rows=()=>[...a.w.document.querySelectorAll('.ft-sheet-row')];assert.equal(rows().length,sex==='mujer'?6:5);
  assert.deepEqual(rows().map(b=>b.childNodes[1].textContent),['Entreno','Comida','Peso','Nota del día','Medidas',...(sex==='mujer'?['Check-in de ciclo']:[])]);
  await a.click('.ft-sheet-panel');assert.equal(a.app.sheet,'add');await a.click('.ft-sheet');assert.equal(a.app.sheet,null);
  const targets=['entrenar','nutricion','peso','nota','medidas',...(sex==='mujer'?['checkin']:[])];for(let i=0;i<targets.length;i++){await a.act(()=>a.app.goTo('diario'));await a.click('.ft-nav-add');await a.act(()=>rows()[i].click());assert.equal(a.app.tab,targets[i]);assert.equal(a.app.sheet,null);}
  await a.click('.ft-nav-add');await a.click('.ft-sheet button[aria-label="Cerrar"]');assert.equal(a.app.sheet,null);
 });},
 async routing(options={}) {await done(await mountInterface(seed,{mode:'app'},options),async a=>{await a.ready();await a.act(()=>a.app.goTo('peso',prior));assert.equal(a.app.focusDate,prior);await heading(a,'Cuerpo');assert.equal(a.w.document.querySelector('input[type=date]').value,prior);await a.act(()=>a.app.goTo('diario'));assert.equal(a.app.focusDate,null);await a.act(()=>a.app.goTo('peso'));await heading(a,'Cuerpo');assert.equal(a.w.document.querySelector('input[type=date]').value,date);await a.act(()=>a.app.openCard('peso'));assert.equal(a.app.tab,'dashboard');assert.equal(a.app.focusDate,null);await a.act(()=>a.app.goTo('destino-actual-desconocido',prior));assert.equal(a.app.tab,'destino-actual-desconocido');assert.equal(a.app.focusDate,prior);});},
 async account(){await done(await mountInterface(seed,{mode:'account',section:'perfil'}),async a=>{
  assert(a.text.includes('PERFIL'));assert.equal(a.w.document.querySelector('.ft-dc-chips .on').textContent,'PERFIL');await a.button('DATOS Y CONFIGURACIÓN');assert.equal(a.w.document.querySelector('.ft-dc-chips .on').textContent,'DATOS Y CONFIGURACIÓN');await a.render({mode:'account',section:'perfil'});assert.equal(a.w.document.querySelector('.ft-dc-chips .on').textContent,'DATOS Y CONFIGURACIÓN');await a.render({mode:'account',section:'perfil'},true);assert.equal(a.w.document.querySelector('.ft-dc-chips .on').textContent,'PERFIL');await a.render({mode:'account',section:'datos'},true);assert(a.text.includes('Elegir archivo'));await a.button('Elegir archivo');assert.deepEqual(plain(a.events.at(-1)),['import']);
 });},
 async 'body-routing'(){await done(await mountInterface(seed,{mode:'app'}),async a=>{await a.ready();for(const tab of ['cuerpo','peso','medidas','nota']){await a.act(()=>a.app.goTo(tab,prior));await heading(a,'Cuerpo');assert.equal(a.w.document.querySelector('input[type=date]').value,prior);assert.equal(a.app.tab,tab);assert.equal(findButton(a,'CHECK-IN'),undefined);}await a.act(()=>a.app.setGoals(g=>({...g,sex:'mujer'})));await a.act(()=>a.app.goTo('checkin',prior));await heading(a,'Cuerpo');assert(findButton(a,'CHECK-IN'));assert(a.text.includes('Guardar ciclo'));});},
 async diary(){
  const data={weights:Array.from({length:461},(_,i)=>({id:'w'+i,date:addDays(date,-i),kg:70})),workouts:[{id:'match',date,exercises:[{name:'Remo exacto',sets:[]}]}]};
  assert.deepEqual(searchFeed(' r ',data),[]);const results=searchFeed(' 70 KG ',data);assert.equal(results.length,40);assert.equal(results[0].date,date);assert.equal(results[39].date,addDays(date,-39));assert.equal(searchFeed('70 kg',data,{limit:1000}).length,460);const matched=searchFeed('REMO',data);assert.equal(matched.length,1);assert(matched[0].meta.includes('Remo exacto'));
  await done(await mountInterface(seed,{mode:'diary'}),async a=>{const chips=[...a.w.document.querySelectorAll('.ft-dc-chips button')];const weight=chips.find(b=>b.textContent==='PESO');assert(weight);await a.act(()=>weight.click());assert.equal(weight.getAttribute('aria-pressed'),'false');await a.render({mode:'diary'});assert.equal(a.w.document.querySelector('.ft-dc-chips button.off').textContent,'PESO');});
 },
 async plan(){await done(await mountInterface({...seed,weights:[{id:'old',date:prior,kg:69}],routines:[{id:'r',name:'Rutina',suggestedDay:6,exercises:[]}]},{mode:'plan'}),async a=>{await a.act(()=>a.w.document.querySelectorAll('.ft-plan-week button')[5].click());const entry=[...a.w.document.querySelectorAll('button.ft-dc-row')].find(b=>b.textContent.includes('69'));assert(entry);await a.act(()=>entry.click());assert.deepEqual(plain(a.events.at(-1)),['navigate','peso',prior]);for(const b of [...a.w.document.querySelectorAll('.ft-dc-acts button')]){if(/Entreno|Comida|Nota|Medidas/.test(b.textContent)){await a.act(()=>b.click());assert.equal(a.events.at(-1)[2],prior);}}const routine=findButton(a,'Ver y editar la rutina completa');assert(routine);await a.act(()=>routine.click());assert.deepEqual(plain(a.events.at(-1)),['navigate','rutinas']);});},
 async 'metric-focus'(){await done(await mountInterface(seed,{mode:'dashboard'}),async a=>{
  await a.render({mode:'dashboard',focusCard:'peso'});assert.equal(a.w.__interfaceScroll.at(-1).id,'card-peso');assert(a.w.document.querySelector('#card-peso.ft-dc-focus'));assert(a.events.some(e=>e[0]==='focused'));await a.advance(2199);assert(a.w.document.querySelector('#card-peso.ft-dc-focus'));await a.advance(1);assert.equal(a.w.document.querySelector('#card-peso.ft-dc-focus'),null);
  await a.act(()=>a.w.__interfaceDashboard.setFilter('fuerza'));assert.equal(a.w.document.querySelector('#card-peso'),null);const n=a.events.filter(e=>e[0]==='focused').length;await a.render({mode:'dashboard',focusCard:'macros'});assert.equal(a.w.__interfaceDashboard.filter,'all');assert.equal(a.events.filter(e=>e[0]==='focused').length,n);await a.render({mode:'dashboard',focusCard:'inexistente'});assert.equal(a.events.filter(e=>e[0]==='focused').length,n);
 });},
 async theme(options={}){for(const pref of [null,'dark','light','auto','invalido'])await done(await mountInterface({}, {mode:'app'}, {...options,setup:w=>{if(pref!==null)w.localStorage.setItem('ft-theme',pref);}}),async a=>{await a.ready();assert.equal(a.app.themePref,['auto','light','dark'].includes(pref)?pref:'dark');assert.equal(a.modules.utils.readThemePref(),a.app.themePref);assert.equal(a.modules.utils.resolveTheme('auto',true),'dark');assert.equal(a.modules.utils.resolveTheme('auto',false),'light');await a.act(()=>a.app.setThemePref('light'));assert.equal(a.w.localStorage.getItem('ft-theme'),'light');assert.equal(a.w.document.documentElement.dataset.theme,'light');});
  await done(await mountInterface({}, {mode:'app'},{setup:w=>{Object.defineProperty(w,'localStorage',{value:{getItem(){throw Error('bloqueado');},setItem(){throw Error('bloqueado');}}});}}),async a=>{await a.ready();assert.equal(a.app.theme,'dark');await a.act(()=>a.app.setThemePref('light'));assert.equal(a.app.theme,'light');});
 },
 async 'theme-lifecycle'(){await done(await mountInterface({}, {mode:'app'},{setup:w=>w.localStorage.setItem('ft-theme','auto')}),async a=>{await a.ready();assert.equal(a.mediaListeners.size,1);assert.equal(a.app.theme,'light');await a.media(true);assert.equal(a.app.theme,'dark');await a.act(()=>a.app.setThemePref('light'));await a.media(true);assert.equal(a.app.theme,'light');await a.act(()=>a.w.__interfaceUnmount());assert.equal(a.mediaListeners.size,0);});
  const html=await readFile('index.html','utf8');const script=html.match(/<script>([\s\S]*?)<\/script>/)[1];for(const pref of ['dark','light','auto','invalido'])await done(await mountInterface({}, {mode:'blank'}),async a=>{a.w.localStorage.setItem('ft-theme',pref);a.w.eval(script);assert.equal(a.w.document.documentElement.dataset.theme,pref==='dark'?'dark':'light');if(pref==='invalido'){await a.render({mode:'app'});await a.ready();assert.equal(a.app.theme,'dark');}});
 },
 async toast(options={}){await done(await mountInterface({}, {mode:'blank'},options),async a=>{await a.act(()=>a.w.__interfaceToast('antes'));await a.render({mode:'toast'});assert.equal(a.w.document.querySelector('[role=status]'),null);await a.act(()=>a.w.__interfaceToast('primero'));let el=a.w.document.querySelector('[role=status]');assert.equal(el.textContent,'primero');assert.equal(el.getAttribute('aria-live'),'polite');await a.advance(2000);await a.act(()=>a.w.__interfaceToast('segundo'));await a.act(()=>a.w.__interfaceToast(''));await a.advance(600);assert(a.w.document.querySelector('[role=status]'),'FR-011 el mensaje nuevo conserva su plazo');assert.equal(a.w.document.querySelector('[role=status]').textContent,'segundo');await a.advance(1999);assert(a.w.document.querySelector('[role=status]'));await a.advance(1);assert.equal(a.w.document.querySelector('[role=status]'),null);await a.render({mode:'toast',ms:123});await a.act(()=>a.w.__interfaceToast('corto'));await a.advance(122);assert(a.w.document.querySelector('[role=status]'));await a.advance(1);assert.equal(a.w.document.querySelector('[role=status]'),null);await a.render({mode:'blank'});await a.act(()=>a.w.__interfaceToast('sin suscriptor'));await a.render({mode:'toast'});assert.equal(a.w.document.querySelector('[role=status]'),null);});}
};
Object.assign(cases,{
 async boot(){
  let release;const gate=new Promise(r=>release=r);await done(await mountInterface({}, {mode:'app'},{fixture:{onGetSession:()=>gate}}),async a=>{assert(a.text.includes('Cargando'));await a.act(()=>release({data:{session:null}}));await waitFor(()=>a.text.includes('Correo electrónico'),'auth sin sesión');assert.equal(a.app.session,null);});
  await done(await mountInterface({}, {mode:'app'},{fixture:{onGetSession:()=>({error:{message:'fallo006'},data:{session:null}})}}),async a=>{await waitFor(()=>a.text.includes('No se pudo verificar'),'fallo sesión');a.fixture.onGetSession=undefined;await a.button('Reintentar');await a.ready();assert.equal(a.app.loaded,true);});
  await done(await mountInterface({}, {mode:'app'},{fixture:{onRead:()=>({error:{message:'fallo lectura'}})}}),async a=>{await waitFor(()=>a.text.includes('No pudimos cargar tus datos'),'fallo carga');a.fixture.onRead=undefined;await a.button('Reintentar');await a.ready();assert.equal(a.app.loaded,true);a.fixture.failWrites=true;await a.act(()=>a.app.setGoals(g=>({...g,targetWeight:61})));await waitFor(()=>a.text.includes('Error al guardar'),'error guardar');assert.equal(a.w.document.querySelector('[role=status]'),null);});
  let resolveLazy;await done(await mountInterface({}, {mode:'app'},{setup:w=>w.__interfaceLazyGate=new Promise(r=>resolveLazy=r)}),async a=>{await a.ready();assert(a.text.includes('Cargando Diario'));await a.act(()=>resolveLazy());await heading(a,'Diario');});
  for(const pref of ['light','dark'])await done(await mountInterface({}, {mode:'error'},{setup:w=>w.localStorage.setItem('ft-theme',pref)}),async a=>{assert(a.text.includes('FitTrack no pudo mostrar esta pantalla'));assert(findButton(a,'Recargar'));assert(a.w.document.querySelector('main').style.background);});
 },
 async detail(){for(const empty of [false,true])await done(await mountInterface({}, {mode:'detail',empty}),async a=>{assert.equal(a.w.document.querySelector('[role=dialog]').getAttribute('aria-label'),'Desglose sintético');assert.equal(a.w.document.querySelector('[role=dialog]').getAttribute('aria-modal'),'true');if(!empty){assert(a.text.includes('42 kcal'));assert(a.text.includes('12 kg'));assert(a.text.includes('Datos sintéticos'));}else{assert(!a.text.includes('42 kcal'));assert(!a.text.includes('Lectura original'));}await a.click('.ft-sheet-panel');assert.equal(a.state.show,true);await a.click('.ft-sheet');assert.equal(a.state.show,false);await a.button('Abrir detalle');await a.click('button[aria-label="Cerrar"]');assert.equal(a.state.show,false);});},
 async responsive(options={}){await done(await mountInterface({}, {mode:'blank'},options),async a=>{const css=a.modules.fit.CSS;const golden=JSON.parse(await readFile('test-support/interface-golden.json','utf8'));assert.equal(createHash('sha256').update(css.replace(/\r\n/g,'\n')).digest('hex'),golden.cssHash);assert(css.trimStart().startsWith('@import url('));assert(css.includes('@media (max-width:720px)'));assert(css.includes('@media (max-width:959px)'));assert(css.includes('@media (min-width:960px)'));assert(css.includes('minmax(380px,1fr)'));assert(css.includes('@media (max-width:420px)'));});},
 async session(){await done(await mountInterface({}, {mode:'session',exercises:[{id:'e',name:'Remo',primary:'Espalda',targetReps:8,sets:[{id:'s',reps:'',kg:'',rpe:''}]}]}),async a=>{assert(a.w.document.querySelector('.ft-root.ft-focus'));assert(a.text.includes('Remo'));await a.render({mode:'blank'});assert.equal(a.w.document.querySelector('.ft-root.ft-focus'),null);assert.equal(a.intervals.size,0);});},
 async touch(){await done(await mountInterface({}, {mode:'blank'}),async a=>{const css=a.modules.fit.CSS;assert(css.includes('.ft-dc-head{position:sticky;top:0;z-index:20;'));assert(css.includes('.ft-dc-step.sm{width:26px;height:26px'));assert(css.includes('.ft-root .ft-dc-step,.ft-root .ft-dc-step.sm{width:40px;height:40px'));assert(css.includes('.ft-root .ft-trash,.ft-root .ft-addset,.ft-root .ft-iconbtn{min-height:40px;min-width:40px;}'));});},
 async screens(){await done(await mountInterface(seed,{mode:'app'}),async a=>{await a.ready();await a.act(()=>a.app.goTo('biblioteca'));await heading(a,'Bibliotecas');assert.equal(a.w.document.querySelector('.ft-lib-detail'),null);await a.button('Nuevo alimento');assert(a.w.document.querySelector('.ft-lib-detail'));await a.button('Cerrar');assert.equal(a.w.document.querySelector('.ft-lib-detail'),null);await a.act(()=>a.app.goTo('nutricion',prior));await heading(a,'Nutrición');assert.equal(a.w.document.querySelector('input[type=date]').value,prior);await a.button('Añadir comida');await heading(a,'Añadir comida');await a.button('Cerrar');await heading(a,'Nutrición');await a.act(()=>a.app.goTo('medidas',prior));await heading(a,'Cuerpo');assert(a.text.includes('cintura'));assert(!a.text.includes('Guardar bienestar'));});},
 async editorial(){await done(await mountInterface({}, {mode:'editorial',values:[]}),async a=>{assert.equal(a.w.document.querySelector('svg[aria-hidden=true] polyline'),null);await a.render({mode:'editorial',values:[2,4]});assert.equal(a.w.document.querySelector('polyline').getAttribute('points'),'3.0,42.0 187.0,4.0');assert.equal(a.w.document.querySelector('polyline').parentElement.getAttribute('aria-hidden'),'true');await a.click('button[aria-label="Día anterior"]');assert.equal(a.state.date,'2026-10-17');await a.click('button[aria-label="Día siguiente"]');assert.equal(a.state.date,date);await a.resize(639);assert.equal(a.w.document.querySelector('.ft-dc-strip').style.getPropertyValue('--cols'),'2');await a.resize(640);assert.equal(a.w.document.querySelector('.ft-dc-strip').style.getPropertyValue('--cols'),'3');await a.render({mode:'blank'});const added=a.listeners.filter(e=>e[0]==='add'&&e[1]==='resize');const removed=a.listeners.filter(e=>e[0]==='remove'&&e[1]==='resize');assert(added.length>=2);assert(added.every(e=>removed.some(r=>r[2]===e[2])));assert([...a.timers.values()].filter(t=>[40,60,80].includes(t.ms)).every(t=>t.cleared||t.fired));});},
 async previews(){for(const entry of ['src/preview-main.jsx','preview/maqueta.jsx']){const p=await mountInterfacePreview(entry);try{assert(p.w.document.querySelector('.ft-root'));const isMain=entry.startsWith('src/');if(isMain){assert.equal(p.w.document.querySelector('.ft-root').dataset.theme,'dark');await p.button('Cuerpo');await waitFor(()=>p.text.includes('Guardar pesaje'),'peso preview');await p.button('MEDIDAS');assert(p.text.includes('cintura'));await p.button('Tema dark');assert.equal(p.w.document.querySelector('.ft-root').dataset.theme,'light');}else{assert.equal(p.w.document.querySelector('.ft-root').dataset.theme,'dark');assert(p.text.includes('Maqueta')||p.text.includes('Diario'));}}finally{p.close();}}},
 async compatibility(){await done(await mountInterface({}, {mode:'blank'}),async a=>{const gold=JSON.parse(await readFile('test-support/interface-golden.json','utf8'));assert.deepEqual(Object.keys(a.modules.fit).sort(),gold.fitExports);assert.deepEqual(Object.keys(a.modules.utils).sort(),gold.utilsExports);const b=JSON.parse(await readFile('specs/005-cuerpo-ciclo/evidence/baseline.json','utf8'));const pins=[...b.pins,...b.previousPinsVerified];assert.equal(pins.length,68);for(const pin of pins)assert.equal(createHash('sha256').update((await readFile(pin.file,'utf8')).replace(/\r\n/g,'\n')).digest('hex'),pin.sha256,pin.file);assert.equal(createHash('sha256').update(a.modules.fit.CSS.replace(/\r\n/g,'\n')).digest('hex'),gold.cssHash);});},
 async dismiss(){await done(await mountInterface({goals:{sex:'mujer',dismissedAlerts:{other:'2026-10-01'}}},{mode:'diary'}),async a=>{const before=a.w.document.querySelectorAll('.ft-dc-alert').length;assert(before>0);await a.click('.ft-dc-x');const keys=Object.keys(a.state.goals.dismissedAlerts).filter(k=>k!=='other');assert.equal(keys.length,1);assert.equal(a.state.goals.dismissedAlerts[keys[0]],date);assert.equal(a.w.document.querySelectorAll('.ft-dc-alert').length,before-1);assert.equal(a.state.goals.dismissedAlerts.other,'2026-10-01');await a.act(()=>[...a.w.document.querySelectorAll('button')].find(b=>b.textContent.includes('Descartado «')).click());assert.deepEqual(plain(a.state.goals.dismissedAlerts),{other:'2026-10-01'});for(const [when,count]of [['2026-10-12',before-1],['2026-10-11',before]]){await a.act(()=>a.state.setGoals(g=>({...g,dismissedAlerts:{[keys[0]]:when}})));assert.equal(a.w.document.querySelectorAll('.ft-dc-alert').length,count);}});}
});
// Subcasos independientes de la aclaración de foco FR-008, sobre el mismo original.
const originalPlan=cases.plan;cases.plan=async()=>{await originalPlan();await done(await mountInterface(seed,{mode:'plan'}),async a=>{
 await a.act(()=>a.w.document.querySelectorAll('.ft-plan-week button')[6].click());
 const rows=[...a.w.document.querySelectorAll('button.ft-dc-row')];assert.equal(rows.length,4);
 const routes=[];for(const b of rows){await a.act(()=>b.click());routes.push(a.events.at(-1)[1]);assert.equal(a.events.at(-1)[2],date);}assert.deepEqual(routes.sort(),['medidas','nota','nutricion','peso']);
 const train=[...a.w.document.querySelectorAll('button')].find(b=>b.textContent.includes('Ver sesión')||b.textContent.includes('Continuar')||b.textContent.trim()==='Registrar entreno');
 // La sesión tiene su acción propia: todas las filas del resto del día ya se comprobaron.
 assert(a.text.includes('Remo'));await a.act(()=>a.w.document.querySelectorAll('.ft-plan-week button')[5].click());
 for(const label of ['Añadir comida','Escribir nota']){await a.button(label);assert.equal(a.events.at(-1)[2],prior);}
 });};
const originalDetail=cases.detail;cases.detail=async()=>{await originalDetail();await done(await mountInterface({goals:{...paceGoals,sex:'hombre'},weights:paceWeights()},{mode:'diary'}),async a=>{await a.button('POR QUÉ VEO ESTO');const dialog=a.w.document.querySelector('[role=dialog]');assert(dialog);assert(dialog.textContent.includes('7700'));assert(dialog.getAttribute('aria-label').startsWith('De dónde salen las'));await a.click('button[aria-label="Cerrar"]');assert.equal(a.w.document.querySelector('[role=dialog]'),null);});};
const originalThemeLifecycle=cases['theme-lifecycle'];cases['theme-lifecycle']=async()=>{await originalThemeLifecycle();
 await done(await mountInterface({}, {mode:'app'},{noMedia:true}),async a=>{await a.ready();assert.equal(a.app.theme,'dark');assert.equal(a.mediaListeners.size,0);});
 await done(await mountInterface({}, {mode:'app'}),async a=>{await a.ready();await a.act(()=>a.app.setThemePref('dark'));await a.media(false);assert.equal(a.app.theme,'dark');});
 const script=(await readFile('index.html','utf8')).match(/<script>([\s\S]*?)<\/script>/)[1];
